css:
:where(.wtyg-map-law_atlas){--peat:#23201c; --peat2:#2e2a25; --peat3:#3a352f;
  --bone:#e6dfd3; --ash:#a89f92; --line:rgba(230,223,211,.16);
  --drafted:#9a6a95; --unequal:#7193ad; --capture:#9a5458; --isds:#5b8a84; --evidence:#8a9870;
  --serif:"Newsreader",Georgia,"Times New Roman",serif;
  --cond:"IBM Plex Sans Condensed","Arial Narrow",Arial,sans-serif;}
:where(.wtyg-map-law_atlas) *{box-sizing:border-box}
:where(.wtyg-map-law_atlas) button{font:inherit;color:inherit}
:where(.wtyg-map-law_atlas) :focus-visible{outline:2px solid var(--bone);outline-offset:2px}
:where(.wtyg-map-law_atlas) a{color:#cdbfd6}
:where(.wtyg-map-law_atlas) .leaflet-container{font-family:var(--cond)}
:where(.wtyg-map-law_atlas) .leaflet-tooltip.tt{background:var(--peat);color:var(--bone);border:1px solid var(--line);border-radius:3px;font-family:var(--cond);font-size:13px;padding:5px 8px;box-shadow:none}
:where(.wtyg-map-law_atlas) .leaflet-tooltip.tt::before{display:none}
:where(.wtyg-map-law_atlas) .tt b{font-weight:600}
:where(.wtyg-map-law_atlas) .narr{font-size:16.5px;line-height:1.62;margin:0}
:where(.wtyg-map-law_atlas) .narr sup a{font-family:var(--cond);font-size:11px;text-decoration:none;color:#cdbfd6;padding:0 1px}
:where(.wtyg-map-law_atlas) ol.refs{font-family:var(--cond);font-size:12.5px;line-height:1.4;color:var(--ash);padding-left:22px;margin:10px 0 0}
:where(.wtyg-map-law_atlas) ol.refs li{margin-top:6px}
:where(.wtyg-map-law_atlas) ol.refs .k{display:block;color:#8f877b}
:where(.wtyg-map-law_atlas) .blk{padding:16px 0;border-bottom:1px solid var(--line)}
:where(.wtyg-map-law_atlas) .blk:last-child{border-bottom:0}
:where(.wtyg-map-law_atlas) .kind{display:flex;align-items:center;gap:8px;font-family:var(--cond);font-size:13px;color:var(--ash);margin-bottom:6px}
:where(.wtyg-map-law_atlas) .kind i{width:10px;height:10px;border-radius:2px;display:inline-block}
:where(.wtyg-map-law_atlas) .blk h3{font-weight:500;font-size:19px;line-height:1.25;margin:0 0 6px}
:where(.wtyg-map-law_atlas) .fig{font-family:var(--cond);font-weight:500;font-size:22px;margin:2px 0 8px;color:var(--bone)}
:where(.wtyg-map-law_atlas) .blk p{font-size:15.5px;line-height:1.55;margin:0 0 8px}
:where(.wtyg-map-law_atlas) .srcs{list-style:none;padding:0;margin:8px 0 0;font-family:var(--cond);font-size:12.5px;line-height:1.4;color:var(--ash)}
:where(.wtyg-map-law_atlas) .srcs li{margin-top:5px}
:where(.wtyg-map-law_atlas) .srcs .k{display:block;color:#8f877b}
:where(.wtyg-map-law_atlas) .bar{position:relative;height:8px;background:var(--peat3);border-radius:2px;margin:6px 0 4px}
:where(.wtyg-map-law_atlas) .bar span{position:absolute;inset:0 auto 0 0;border-radius:2px}
:where(.wtyg-map-law_atlas) .bscale{display:flex;justify-content:space-between;font-family:var(--cond);font-size:11.5px;color:var(--ash)}
:where(.wtyg-map-law_atlas) table.mini{width:100%;border-collapse:collapse;font-family:var(--cond);font-size:13px;margin-top:6px}
:where(.wtyg-map-law_atlas) table.mini td{padding:4px 0;border-bottom:1px solid var(--line)}
:where(.wtyg-map-law_atlas) table.mini td:last-child{text-align:right}
:where(.wtyg-map-law_atlas) .gaps{font-size:14px;line-height:1.5;color:var(--ash)}
:where(.wtyg-map-law_atlas) .gaps ul{margin:6px 0 0;padding-left:18px}
:where(.wtyg-map-law_atlas) .tablewrap{overflow:auto}
:where(.wtyg-map-law_atlas) table.cmp{border-collapse:collapse;width:100%;font-family:var(--cond);font-size:14px}
:where(.wtyg-map-law_atlas) table.cmp th{position:sticky;top:0;background:var(--peat2);text-align:left;font-weight:500;padding:9px 10px;border-bottom:1px solid var(--line);cursor:pointer;white-space:nowrap;color:var(--bone)}
:where(.wtyg-map-law_atlas) table.cmp th[aria-sort]::after{content:"";}
:where(.wtyg-map-law_atlas) table.cmp th[aria-sort="ascending"]::after{content:" ▲";font-size:10px}
:where(.wtyg-map-law_atlas) table.cmp th[aria-sort="descending"]::after{content:" ▼";font-size:10px}
:where(.wtyg-map-law_atlas) table.cmp td{padding:7px 10px;border-bottom:1px solid var(--line);white-space:nowrap}
:where(.wtyg-map-law_atlas) table.cmp tbody tr{cursor:pointer}
:where(.wtyg-map-law_atlas) table.cmp tbody tr:hover{background:var(--peat2)}
:where(.wtyg-map-law_atlas) table.cmp td.num{text-align:right;font-variant-numeric:tabular-nums}
:where(.wtyg-map-law_atlas) table.cmp td.na{color:#6f685e}
:where(.wtyg-map-law_atlas) .folded .fold svg{transform:rotate(180deg)}
:where(.wtyg-map-law_atlas) .dots{display:inline-flex;gap:2px}
:where(.wtyg-map-law_atlas) .dots i{width:6px;height:6px;border-radius:50%;background:var(--peat3);display:inline-block}
:where(.wtyg-map-law_atlas) .dots i.on{background:var(--bone)}
:where(.wtyg-map-law_atlas) .cbar{display:grid;grid-template-columns:1fr 46px;gap:2px 8px;align-items:center;font-family:var(--cond);font-size:13px;margin-top:10px}
:where(.wtyg-map-law_atlas) .cbar .lb{color:var(--bone)}
:where(.wtyg-map-law_atlas) .cbar .lb small{display:block;color:var(--ash);font-size:11.5px;line-height:1.3;margin-top:1px}
:where(.wtyg-map-law_atlas) .cbar .v{text-align:right;font-variant-numeric:tabular-nums}
:where(.wtyg-map-law_atlas) .cbar .bar{grid-column:1/3;margin:3px 0 0}
:where(.wtyg-map-law_atlas) .big{font-family:var(--cond);font-size:40px;font-weight:500;line-height:1}
:where(.wtyg-map-law_atlas) .big small{font-size:15px;color:var(--ash);font-weight:400;margin-left:6px}
:where(.wtyg-map-law_atlas) .sq{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:7px;vertical-align:-1px}
:where(.wtyg-map-law_atlas) .areat th[scope=row]{text-align:left;font-weight:400}
:where(.wtyg-map-law_atlas) .ppop .leaflet-popup-content-wrapper,:where(.wtyg-map-law_atlas) .ppop .leaflet-popup-tip{background:var(--peat);color:var(--bone);border:1px solid var(--line);border-radius:4px}
:where(.wtyg-map-law_atlas) .ppop .leaflet-popup-content{margin:12px 14px;font-family:var(--serif,Georgia,serif);font-size:14px;line-height:1.45}
:where(.wtyg-map-law_atlas) .pp h3{margin:2px 0 2px;font-size:17px;font-weight:500}
:where(.wtyg-map-law_atlas) .pp .pk,:where(.wtyg-map-law_atlas) .pp .pr,:where(.wtyg-map-law_atlas) .pp .pl{font-family:var(--cond);font-size:12.5px;color:var(--ash)}
:where(.wtyg-map-law_atlas) .pp p{margin:8px 0}
:where(.wtyg-map-law_atlas) .pp .pl{margin-bottom:4px}
:where(.wtyg-map-law_atlas) .ssv{margin:6px 0 4px;border-top:1px solid var(--line);padding-top:6px}
:where(.wtyg-map-law_atlas) .ssv>summary{cursor:pointer;font-family:var(--cond);font-size:13px;color:var(--ash);padding:4px 6px;list-style:none}
:where(.wtyg-map-law_atlas) .ssv>summary::before{content:"▸ ";}
:where(.wtyg-map-law_atlas) .ssv[open]>summary::before{content:"▾ ";}
:where(.wtyg-map-law_atlas) .ssv>summary::-webkit-details-marker{display:none}
:where(.wtyg-map-law_atlas) .arch{color:var(--ash);text-decoration:underline dotted;font-size:.95em}
:where(.wtyg-map-law_atlas){--ink:#1c2023;--ink2:#262b2f;--ink3:#353b40;--paper:#e2ddd3;--mute:#9c9a92;--rule:rgba(226,221,211,.13);
 --peat:var(--ink);--peat2:var(--ink2);--peat3:var(--ink3);--bone:var(--paper);--ash:var(--mute);--line:var(--rule);
 --railL:340px;--railR:316px;--railbg:rgba(28,32,35,.97)}
:where(.wtyg-map-law_atlas) a{color:#b7c3bb}
:where(.wtyg-map-law_atlas) .cvb{grid-column:2/4;height:3px;background:var(--ink3);position:relative;border-radius:2px}
:where(.wtyg-map-law_atlas) .cvb span{position:absolute;inset:0 auto 0 0;border-radius:2px}
:where(.wtyg-map-law_atlas) .ppop .leaflet-popup-content-wrapper,:where(.wtyg-map-law_atlas) .ppop .leaflet-popup-tip{border-radius:3px}
:where(.wtyg-map-law_atlas) .som{background:none;border:1px solid var(--rule);border-radius:2px;color:var(--mute);font-family:var(--cond);font-size:11.5px;padding:1px 6px;cursor:pointer;margin-left:6px;vertical-align:1px;white-space:nowrap}
:where(.wtyg-map-law_atlas) .som:hover{color:var(--paper);border-color:rgba(226,221,211,.4)}
:where(.wtyg-map-law_atlas) .som[aria-pressed="true"]{color:var(--paper);background:var(--ink3);border-color:rgba(226,221,211,.4)}
:where(.wtyg-map-law_atlas) .som.back{margin:10px 0 0;font-size:12.5px;padding:4px 8px}
:where(.wtyg-map-law_atlas) .cbar .lb .som{margin-left:4px}
:where(.wtyg-map-law_atlas) .ssel{width:100%;background:var(--ink2);color:var(--paper);border:1px solid var(--rule);border-radius:2px;padding:6px;font-family:var(--cond);font-size:13px;margin:2px 0 8px}
:where(.wtyg-map-law_atlas) ul.svl{list-style:none;margin:0;padding:0;font-family:var(--cond);font-size:13px}
:where(.wtyg-map-law_atlas) ul.svl li{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:5px 0;border-bottom:1px solid var(--rule)}:where(.wtyg-map-law_atlas) .lw-dossier{font-family:var(--serif);color:var(--bone);max-height:520px;overflow:auto}:where(.wtyg-map-law_atlas) .lw-dossier header{padding:6px 2px 10px;border-bottom:1px solid var(--line)}:where(.wtyg-map-law_atlas) .lw-dossier h2{font-weight:500;font-size:28px;line-height:1.05;margin:0 0 6px;letter-spacing:-.02em}:where(.wtyg-map-law_atlas) .lw-dossier .sub{font-family:var(--cond);font-size:13px;color:var(--ash)}:where(.wtyg-map-law_atlas) .lw-dossier .dbody{padding:0 2px 6px}:where(.wtyg-map-law_atlas) .lw-entry{font-family:var(--serif);color:var(--bone)}:where(.wtyg-map-law_atlas) .lw-entry ol.lw-rank{list-style:none;margin:0;padding:0;font-family:var(--cond)}:where(.wtyg-map-law_atlas) .lw-entry ol.lw-rank button{display:grid;grid-template-columns:34px 1fr 40px;gap:4px 8px;align-items:center;width:100%;background:none;border:0;padding:5px 0;text-align:left}
